const log = createLogger('RivetCLI');

export type CLIOptions = {
  userPort?: number;
  rivetPort?: number;
  help?: boolean;
  version?: boolean;
  debug?: boolean;
  noTelemetry?: boolean;
  noBrowser?: boolean;
  framework?: 'nextjs' | 'vite' | 'cra' | 'remix' | 'svelte' | 'static';
  entry?: string;
  styleFramework?: 'tailwind';
  tailwindConfig?: string;
  noGit?: boolean;
};

export const DEFAULT_PORT = 4000;
export const DEFAULT_USER_PORT = 3000;

type AgentDevServerContext = {
  ownership: 'external' | 'none' | 'rivet_owned';
  host: string | null;
  port: number | null;
  startedByRivet: boolean;
};

type AgentDevServerHealth = AgentDevServerContext & {
  isReachable: boolean | null;
  reason: 'healthy' | 'unknown';
  lastCheckedAt: number | null;
};

type AgentDevServerContextOptions = {
  framework: Framework;
  ownership?: AgentDevServerContext['ownership'];
  devServerHost?: string;
  userDevServerPort: number;
  startedByRivet?: boolean;
};

export const buildAgentDevServerContext = ({
  framework,
  ownership,
  devServerHost,
  userDevServerPort,
  startedByRivet,
}: AgentDevServerContextOptions): AgentDevServerContext => {
  if (framework === 'static' || userDevServerPort === 0) {
    return {
      ownership: 'none',
      host: null,
      port: null,
      startedByRivet: false,
    };
  }

  return {
    ownership: ownership ?? 'external',
    host: devServerHost ?? 'localhost',
    port: userDevServerPort,
    startedByRivet: startedByRivet ?? false,
  };
};

type AgentProject = {
  id: string;
  path: string;
  devServerPort: number;
  devServerHost?: string;
  status: 'detected' | 'connected' | 'error';
  packageManager: 'npm' | 'yarn' | 'pnpm';
  framework: Framework;
  entryPoint?: string;
};

type AgentDevServerResolution = {
  project: AgentProject;
  userDevServerPort: number;
  devServerContext: AgentDevServerContext;
  cleanup?: () => Promise<void>;
  ownedProcess?: Extract<StartDevServerResult, { success: true }>['process'];
};

type AgentDevServerResolverOptions = {
  projectPath: string;
  options: Pick<CLIOptions, 'framework' | 'entry' | 'userPort'>;
  detection?: Pick<
    ProjectDetectionService,
    | 'detectProject'
    | 'detectFramework'
    | 'detectPackageManager'
    | 'readConfiguredPort'
    | 'findRunningDevServer'
  >;
  runtime?: DevServerRuntimeService;
};

export const resolveAgentDevServer = async ({
  projectPath,
  options,
  detection = new ProjectDetectionService(),
  runtime = createDevServerRuntimeService(),
}: AgentDevServerResolverOptions): Promise<AgentDevServerResolution> => {
  if (options.userPort) {
    const framework = options.framework ?? 'nextjs';
    const packageManager = await detection.detectPackageManager(projectPath);
    const project: AgentProject = {
      id: path.basename(projectPath),
      framework,
      path: projectPath,
      devServerPort: options.userPort,
      devServerHost: 'localhost',
      status: 'detected',
      packageManager,
    };
    return {
      project,
      userDevServerPort: options.userPort,
      devServerContext: buildAgentDevServerContext({
        framework,
        devServerHost: project.devServerHost,
        userDevServerPort: options.userPort,
      }),
    };
  }

  try {
    const project = (await detection.detectProject(
      projectPath,
      options.framework,
      options.entry,
      options.userPort,
    )) as AgentProject;
    const userDevServerPort = project.devServerPort;
    return {
      project,
      userDevServerPort,
      devServerContext: buildAgentDevServerContext({
        framework: project.framework,
        devServerHost: project.devServerHost,
        userDevServerPort,
      }),
    };
  } catch (error) {
    const isNoServerError =
      error instanceof Error && error.message.includes('No running dev server');
    if (!isNoServerError) {
      throw error;
    }
  }

  const framework = options.framework ?? detection.detectFramework(projectPath);
  const packageManager = await detection.detectPackageManager(projectPath);
  if (framework === 'static') {
    const project: AgentProject = {
      id: path.basename(projectPath),
      framework,
      path: projectPath,
      devServerPort: 0,
      devServerHost: 'localhost',
      status: 'detected',
      packageManager,
      entryPoint: options.entry ?? 'index.html',
    };
    return {
      project,
      userDevServerPort: 0,
      devServerContext: buildAgentDevServerContext({
        framework,
        userDevServerPort: 0,
      }),
    };
  }

  const runningServer = await detection.findRunningDevServer(projectPath);
  if (runningServer) {
    const project: AgentProject = {
      id: path.basename(projectPath),
      framework,
      path: projectPath,
      devServerPort: runningServer.port,
      devServerHost: runningServer.host,
      status: 'detected',
      packageManager,
    };
    return {
      project,
      userDevServerPort: runningServer.port,
      devServerContext: buildAgentDevServerContext({
        framework,
        devServerHost: runningServer.host,
        userDevServerPort: runningServer.port,
      }),
    };
  }

  const preferredPort =
    detection.readConfiguredPort(projectPath) ??
    (framework === 'vite' || framework === 'svelte' ? 5173 : DEFAULT_USER_PORT);
  const started = await runtime.start({
    projectPath,
    framework,
    packageManager,
    preferredPort,
  });
  if (!started.success) {
    throw new Error(started.error);
  }

  const project: AgentProject = {
    id: path.basename(projectPath),
    framework,
    path: projectPath,
    devServerPort: started.port,
    devServerHost: started.host,
    status: 'detected',
    packageManager,
  };
  return {
    project,
    userDevServerPort: started.port,
    devServerContext: buildAgentDevServerContext({
      framework,
      ownership: 'rivet_owned',
      devServerHost: started.host,
      userDevServerPort: started.port,
      startedByRivet: true,
    }),
    cleanup: started.stop,
    ownedProcess: started.process,
  };
};

export const buildAgentDevServerHealth = (
  context: AgentDevServerContext,
): AgentDevServerHealth => ({
  ...context,
  isReachable: context.ownership === 'none' ? null : true,
  reason: context.ownership === 'none' ? 'unknown' : 'healthy',
  lastCheckedAt: Date.now(),
});

export const updateOwnedDevServerHealthOnExit = (
  bridge: Pick<
    SessionBridgeService,
    'getDevServerHealth' | 'isActive' | 'updateDevServerHealth'
  >,
  ownedDevServerPort: number | null,
): void => {
  const currentHealth = bridge.getDevServerHealth();
  if (
    !bridge.isActive() ||
    currentHealth.ownership !== 'rivet_owned' ||
    currentHealth.port !== ownedDevServerPort
  ) {
    return;
  }
  bridge.updateDevServerHealth({
    isReachable: false,
    reason: 'upstream_unreachable',
    lastCheckedAt: Date.now(),
  });
};

export const isAgentVariantsEnabled = (
  options: Pick<CLIOptions, 'noGit'>,
): boolean => !options.noGit;

export const registerOwnedDevServerSignalHandlers = (options: {
  kill: (signal: NodeJS.Signals) => unknown;
}): void => {
  const stopOwnedDevServer = () => {
    try {
      options.kill('SIGTERM');
    } catch {}
  };
  process.prependOnceListener('SIGINT', stopOwnedDevServer);
  process.prependOnceListener('SIGTERM', stopOwnedDevServer);
};

export const authCommandOptionsForArgs = (
  args: string[],
): { noBrowser: boolean; noTelemetry: boolean } => ({
  noBrowser: args.includes('--no-browser'),
  noTelemetry: args.includes('--no-telemetry'),
});

export const rememberInstallRef = (
  args: string[],
  downloadType?: string,
): string[] => {
  const { installRef, remainingArgs } = extractInstallRef(args);
  if (installRef) {
    getConfigManager().setInstallRef(installRef, downloadType);
  }
  return remainingArgs;
};

const reportInstallRefActivations = async (): Promise<void> => {
  const telemetry = new TelemetryService({ source: 'cli' });
  telemetry.reportInstallRefActivations();
  await telemetry.shutdown();
};

const discardInstallRefForValidatedSession = (): void => {
  const configManager = getConfigManager();
  const installRef = configManager.getInstallRef();
  if (installRef) {
    configManager.clearInstallRef(installRef);
  }
};

export const authFailureReasonForError = (
  error: string | undefined,
): 'oauth_failed' | 'timeout' =>
  error?.trim().toLowerCase() === 'timeout' ? 'timeout' : 'oauth_failed';

