const promptYesNo = async (question: string): Promise<boolean> => {
  if (!process.stdin.isTTY) return false;
  const readline = await import('node:readline/promises');
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });
  try {
    const answer = (await rl.question(`${question} [Y/n] `))
      .trim()
      .toLowerCase();
    return answer === '' || answer === 'y' || answer === 'yes';
  } finally {
    rl.close();
  }
};

const promptPostInstall = async (): Promise<void> => {
  const loginCommand = isEphemeralNpxInstall()
    ? 'npx -y rivet-design@latest login'
    : 'rivet login';
  if (!process.stdin.isTTY || process.env.CI === 'true') {
    console.log(
      `\nNext: open your agent and say "Open Rivet". The first time, Rivet opens sign-in in your browser so you can sign in or create an account (\`${loginCommand}\` also works).\n`,
    );
    return;
  }

  if (await new AuthService().ensureAuthenticated()) {
    discardInstallRefForValidatedSession();
    const email = getConfigManager().getEmail();
    console.log(
      `\nYou're signed in${email ? ` as ${email}` : ''}. Open your agent and say "Open Rivet" to start.\n`,
    );
    return;
  }

  const wantsSignIn = await promptYesNo(
    'Sign in or create your Rivet account now?',
  );
  if (wantsSignIn) {
    await handleLogin({
      nextStepHint: 'You\'re all set — open your agent and say "Open Rivet".',
      exitOnFailure: false,
      authEntryPoint: 'install_flow',
    });
  } else {
    console.log(
      `\nNo problem — Rivet opens sign-in in your browser the first time you say "Open Rivet" (or run \`${loginCommand}\` whenever you're ready).\n`,
    );
  }
};

const handleInstall = async (installArgs: string[]): Promise<void> => {
  const { installRef, remainingArgs } = extractInstallRef(installArgs);
  const parsed = parseFlags(remainingArgs, {
    mcp: { takesValue: false },
    'no-mcp': { takesValue: false },
    'no-telemetry': { takesValue: false },
    'caller-agent': { takesValue: true },
    'caller-model': { takesValue: true },
    'caller-session': { takesValue: true },
    handoff: { takesValue: true },
  });
  if (parsed.errors.length > 0) {
    console.error(`Invalid install arguments: ${parsed.errors.join('; ')}`);
    console.error('Usage: rivet install [agent ...] [--no-mcp] [--ref <ref>]');
    process.exit(2);
  }
  const mcp = parsed.values['no-mcp'] !== true;
  const handoff = parseHandoff({
    callerAgent: stringFlag(parsed, 'caller-agent'),
    callerModel: stringFlag(parsed, 'caller-model'),
    callerSession: stringFlag(parsed, 'caller-session'),
    handoffJson: stringFlag(parsed, 'handoff'),
  });
  if (!handoff.ok) {
    console.error(handoff.error);
    process.exit(2);
  }
  const handoffJson = stringFlag(parsed, 'handoff');
  const handoffAgent = handoffJson
    ? (JSON.parse(handoffJson) as { agent?: unknown }).agent
    : undefined;
  const declaredAgent =
    stringFlag(parsed, 'caller-agent')?.trim() ||
    (typeof handoffAgent === 'string' ? handoffAgent.trim() : undefined);
  let callerEvidence: string | undefined;
  if (declaredAgent) {
    callerEvidence = stringFlag(parsed, 'caller-agent')
      ? '--caller-agent'
      : '--handoff.agent';
  }
  const selection = resolveInstallTargets(parsed.positionals, {
    callerAgent: declaredAgent ? handoff.handoff?.agent : undefined,
    callerEvidence,
  });
  if (selection.status === 'invalid') {
    console.error(selection.error);
    process.exit(1);
  }
  if (selection.status === 'confirmation_required') {
    reportInstallConfirmation(selection, installArgs);
    return;
  }
  rememberInstallRef(installArgs, selection.targetIds.join(','));
  if (installRef) await reportInstallRefActivations();

  const bootstrap = await bootstrapGlobalInstall(installArgs);
  if (bootstrap.action === 'reexeced') {
    process.exit(bootstrap.exitCode);
  }
  if (bootstrap.action === 'failed') {
    console.log(bootstrapFailureAdvisory(bootstrap.reason));
  }

  const { exitCode } = installHarnesses(selection.targetIds, { mcp });
  if (exitCode !== 0) process.exit(exitCode);
  await promptPostInstall();
};

const handleUninstall = async (editors: string[]): Promise<void> => {
  const { exitCode } = uninstallHarnesses(editors);
  if (exitCode !== 0) process.exit(exitCode);
};

export const handleLogin = async (
  options: {
    noBrowser?: boolean;
    noTelemetry?: boolean;
    nextStepHint?: string;
    authEntryPoint?: 'install_flow' | 'login_command' | 'signin_command';
    exitOnFailure?: boolean;
  } = {},
): Promise<void> => {
  const nextStepHint = options.nextStepHint ?? 'You can now run: rivet';
  const authEntryPoint = options.authEntryPoint ?? 'login_command';
  const telemetry = new TelemetryService({
    enabled: !options.noTelemetry,
    source: 'cli',
  });
  const finishTelemetry = async (): Promise<void> => {
    telemetry.reportInstallRefActivations();
    await telemetry.shutdown();
  };
  let authAttemptId = '';
  let authStartedAt = 0;
  const startAuthAttempt = (): void => {
    authAttemptId = randomUUID();
    authStartedAt = Date.now();
    telemetry.trackAuthStarted({
      surface: 'cli',
      authAttemptId,
      entryPoint: authEntryPoint,
      method: 'browser_oauth',
    });
  };
  startAuthAttempt();
  console.log('\n🔐 Rivet Login with Google\n');

  const authService = new AuthService();

  const configManager = getConfigManager();
  if (configManager.isAuthenticated()) {
    try {
      const profile = await authService.getValidatedProfile();
      if (profile) {
        discardInstallRefForValidatedSession();
        telemetry.trackAuthCompleted({
          surface: 'cli',
          authAttemptId,
          entryPoint: authEntryPoint,
          method: 'browser_oauth',
          outcome: 'already_authenticated',
          durationMs: Date.now() - authStartedAt,
        });
        await finishTelemetry();
        console.log(`✅ Already signed in as ${configManager.getEmail()}`);
        console.log(`\n${nextStepHint}`);
        return;
      }
    } catch {}
  }

  let pendingFailureReason: 'oauth_failed' | 'timeout' | null = null;
  let isPendingResume = false;
  try {
    const pending = authService.peekPendingLogin();
    if (pending) {
      isPendingResume = true;
      console.log(
        'A sign-in is already in progress. Finish it in the browser, or open:',
      );
      if (pending.authUrl) {
        console.log(`\n  ${pending.authUrl}\n`);
      }
      const resumed = await authService.resumePendingLogin(150);
      if (resumed?.success && resumed.user) {
        telemetry.trackAuthCompleted({
          surface: 'cli',
          authAttemptId,
          entryPoint: authEntryPoint,
          method: 'browser_oauth',
          outcome: 'authenticated',
          durationMs: Date.now() - authStartedAt,
        });
        await finishTelemetry();
        console.log(`✅ Logged in as ${resumed.user.email}`);
        console.log(`\n${nextStepHint}`);
        return;
      }
      if (!resumed) {
        pendingFailureReason = 'timeout';
        console.log('That sign-in was never finished. Starting a new one...');
      } else {
        pendingFailureReason = authFailureReasonForError(resumed.error);
      }
    }
  } catch {
    if (isPendingResume) {
      pendingFailureReason = 'oauth_failed';
    }
  }

  if (pendingFailureReason) {
    telemetry.trackAuthFailed({
      surface: 'cli',
      authAttemptId,
      entryPoint: authEntryPoint,
      method: 'browser_oauth',
      failureReason: pendingFailureReason,
      durationMs: Date.now() - authStartedAt,
    });
    startAuthAttempt();
  }

  console.log(
    options.noBrowser
      ? 'Open this link to sign in:'
      : 'Opening browser to sign in...',
  );
  const loginResult = await authService.loginWithGoogle({
    source: 'cli',
    noBrowser: options.noBrowser,
    onAuthUrl: (url) => {
      console.log(`\n  ${url}\n`);
    },
  });

  if (loginResult.success) {
    telemetry.trackAuthCompleted({
      surface: 'cli',
      authAttemptId,
      entryPoint: authEntryPoint,
      method: 'browser_oauth',
      outcome: 'authenticated',
      durationMs: Date.now() - authStartedAt,
    });
    await finishTelemetry();
    console.log(`✅ Logged in as ${loginResult.user?.email}`);

    console.log(`\n${nextStepHint}`);
    return;
  }

  telemetry.trackAuthFailed({
    surface: 'cli',
    authAttemptId,
    entryPoint: authEntryPoint,
    method: 'browser_oauth',
    failureReason: authFailureReasonForError(loginResult.error),
    durationMs: Date.now() - authStartedAt,
  });
  await finishTelemetry();
  console.log(`❌ Login failed: ${loginResult.error || loginResult.message}`);
  if (options.exitOnFailure ?? true) {
    process.exit(1);
  }
};

const handleLogout = async (): Promise<void> => {
  const configManager = getConfigManager();

  if (!configManager.isAuthenticated()) {
    console.log('❌ Not currently logged in');
    return;
  }

  const email = configManager.getEmail();
  const authService = new AuthService();

  await authService.logout();
  console.log(`✅ Logged out ${email ? `(${email})` : ''}`);
};
